options.getOption:
const data = context.panel.data.series[0];

if (!data || !data.fields || data.fields.length === 0) {
  return {
    graphic: [{
      type: 'text',
      left: 'center',
      top: 'center',
      style: { text: 'Select a command from the dropdown above', fontSize: 16, fill: '#999' }
    }]
  };
}

const roleField = data.fields.find(f => f.name === 'role');
const contentField = data.fields.find(f => f.name === 'content');
const typeField = data.fields.find(f => f.name === 'response_type');
const tsField = data.fields.find(f => f.name === 'ts');

if (!roleField || !contentField) {
  return {
    graphic: [{
      type: 'text',
      left: 'center',
      top: 'center',
      style: { text: 'No conversation data found', fontSize: 16, fill: '#999' }
    }]
  };
}

const echartsInstance = context.panel.chart;
if (!echartsInstance) {
  return { graphic: [{ type: 'text', left: 'center', top: 'center', style: { text: 'Loading...', fill: '#999' } }] };
}
const dom = echartsInstance.getDom();

function escapeHtml(text) {
  if (!text) return '';
  return String(text).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function fmtTs(ts) {
  if (!ts) return '';
  try { return new Date(ts).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit'}); } catch(e) { return ''; }
}

function badge(type) {
  const m = { command:'#1e40af', text:'#374151', thinking:'#6b21a8', tool_use:'#1e3a5f', tool_result:'#14532d', code:'#4a1d96', stderr:'#7f1d1d', approval:'#78350f', end_turn:'#1f2937' };
  return m[type] || '#374151';
}

let html = '<div style="display:flex;flex-direction:column;gap:12px;padding:16px;overflow-y:auto;height:100%;font-family:-apple-system,BlinkMacSystemFont,sans-serif;font-size:13px;line-height:1.5;background:#0b0b0f;">';

for (let i = 0; i < roleField.values.length; i++) {
  const role = roleField.values[i];
  const content = contentField.values[i];
  const type = typeField ? typeField.values[i] : '';
  const ts = tsField ? tsField.values[i] : null;
  const isUser = role === 'user';
  const align = isUser ? 'flex-end' : 'flex-start';
  const bg = isUser ? '#1e40af' : '#1f2937';
  const label = (type || 'unknown').toUpperCase();

  let body = '';
  let txt = content ? String(content) : '';
  const trunc = txt.length > 3000;
  if (trunc) txt = txt.substring(0, 3000);
  const esc = escapeHtml(txt);

  if (type === 'code' || type === 'stderr' || type === 'tool_result') {
    const cbg = type === 'stderr' ? '#2d1111' : type === 'tool_result' ? '#0d2818' : '#1a1a2e';
    body = '<pre style="margin:4px 0;padding:8px 12px;background:'+cbg+';border-radius:6px;font-family:monospace;font-size:12px;white-space:pre-wrap;word-break:break-all;max-height:400px;overflow-y:auto;">'+esc+'</pre>';
  } else if (type === 'thinking') {
    body = '<div style="border-left:3px solid #7c3aed;padding-left:12px;font-style:italic;color:#a78bfa;">'+esc.replace(/\n/g,'<br>')+'</div>';
  } else if (type === 'tool_use') {
    body = '<pre style="margin:4px 0;padding:8px 12px;background:#0c2d48;border-radius:6px;font-family:monospace;font-size:12px;white-space:pre-wrap;word-break:break-all;">'+esc+'</pre>';
  } else {
    body = '<div style="white-space:pre-wrap;word-break:break-word;">'+esc+'</div>';
  }
  if (trunc) body += '<div style="color:#f59e0b;font-size:11px;margin-top:4px;">[truncated]</div>';

  html += '<div style="display:flex;flex-direction:column;align-items:'+align+';">';
  html += '<div style="max-width:85%;background:'+bg+';border-radius:12px;padding:10px 14px;color:#e5e7eb;">';
  html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">';
  html += '<span style="padding:2px 8px;border-radius:4px;font-size:10px;font-weight:600;letter-spacing:0.5px;background:'+badge(type)+';color:#e5e7eb;">'+label+'</span>';
  const stamp = fmtTs(ts);
  if (stamp) html += '<span style="font-size:11px;color:#9ca3af;">'+stamp+'</span>';
  html += '</div>';
  html += body;
  html += '</div></div>';
}

html += '</div>';

let chatDiv = dom.querySelector('#chat-replay');
if (!chatDiv) {
  chatDiv = document.createElement('div');
  chatDiv.id = 'chat-replay';
  chatDiv.style.cssText = 'position:absolute;top:0;left:0;right:0;bottom:0;z-index:10;overflow:hidden;';
  dom.style.position = 'relative';
  dom.appendChild(chatDiv);
}
chatDiv.innerHTML = html;

return {};
